let icUsers=[];const byId=id=>document.getElementById(id),escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function request(path,method='GET',data){const r=await fetch(path,{method,headers:{'content-type':'application/json','x-ic-request':'1'},...(data?{body:JSON.stringify(data)}:{})});if(r.status===401){location.assign('/');throw Error('Phiên đăng nhập đã hết hạn.')}const out=await r.json();if(!r.ok)throw Error(out.error||'Có lỗi xảy ra.');return out}
function showDialog(html){byId('dialog').innerHTML=html+'<div class="dialog-actions"><button data-action="close">Đóng</button></div>';if(!byId('dialog').open)byId('dialog').showModal()}
let issued=null;
function credentials(data){issued=data;showDialog(`<h2>Đã cấp thông tin đăng nhập</h2><p class="muted">Sao chép để giao cho học viên. User có thể đổi mật khẩu sau khi đăng nhập.</p><div class="credential-box"><span>TÊN ĐĂNG NHẬP</span><code>${escapeHtml(data.username)}</code><span>MẬT KHẨU MỚI</span><code>${escapeHtml(data.password)}</code></div><div class="dialog-actions"><button class="primary" data-action="copy">Sao chép thông tin</button></div>`)}
function renderUsers(){const term=byId('search').value.toLowerCase();byId('users').innerHTML=icUsers.filter(u=>u.role!=='admin'&&(u.name+' '+u.username).toLowerCase().includes(term)).map(u=>`<article class="admin-card user-row"><div><div class="user-name">${escapeHtml(u.name)}</div><div class="user-handle">${escapeHtml(u.username)}</div><span class="badge ${u.disabled?'disabled':''}">${u.disabled?'Đã khóa':'Đang hoạt động'}</span></div><div><div class="course-bars">${Object.entries(u.progress.subjects).map(([code,s])=>`<label>${code}<small>${s.done}/${s.total}</small><div class="bar"><i style="width:${s.done/s.total*100}%"></i></div></label>`).join('')}</div><p class="muted" style="font-size:10px;margin-bottom:0">${u.progress.done}/959 câu · ${u.progress.accuracy}% đúng · ${u.progress.examCount} bài thi</p></div><div class="user-actions"><button data-action="detail" data-id="${u.id}">Xem tiến độ</button><button data-action="reset" data-id="${u.id}">Đặt lại mật khẩu</button><button data-action="toggle" data-id="${u.id}">${u.disabled?'Mở tài khoản':'Khóa tài khoản'}</button><button class="danger" data-action="delete-user" data-id="${u.id}">Xóa tài khoản</button></div></article>`).join('')||'<section class="admin-card muted">Chưa có học viên phù hợp. Nhập họ tên ở trên để cấp tài khoản đầu tiên.</section>'}
async function load(){try{icUsers=(await request('/api/admin/users')).users;const students=icUsers.filter(u=>u.role!=='admin');byId('total').textContent=students.length;byId('active').textContent=students.filter(u=>u.progress.lastAnswer>Date.now()-7*86400000).length;byId('average').textContent=students.length?Math.round(students.reduce((n,u)=>n+u.progress.done/959*100,0)/students.length)+'%':'0%';byId('updated').textContent=' '+new Date().toLocaleTimeString('vi-VN');byId('error').textContent='';renderUsers()}catch(e){byId('error').textContent=e.message}}
byId('create').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{credentials(await request('/api/admin/users','POST',{name:byId('name').value}));byId('name').value='';await load()}catch(e){byId('error').textContent=e.message}finally{b.disabled=false}});
byId('search').addEventListener('input',renderUsers);byId('refresh').addEventListener('click',load);
byId('logout').addEventListener('click',async()=>{await request('/api/logout','POST',{});location.assign('/')});
byId('password-open').addEventListener('click',()=>showDialog('<h2>Đổi mật khẩu quản trị</h2><form id="change-password"><label>Mật khẩu hiện tại<input name="current" type="password" autocomplete="current-password" required></label><label>Mật khẩu mới (ít nhất 12 ký tự)<input name="new" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><p class="error" id="password-error"></p><button class="primary">Lưu mật khẩu</button></form>'));
document.addEventListener('submit',async e=>{if(e.target.id!=='change-password')return;e.preventDefault();try{await request('/api/password','POST',{currentPassword:e.target.elements.current.value,password:e.target.elements.new.value});byId('dialog').close()}catch(e){byId('password-error').textContent=e.message}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const u=icUsers.find(u=>u.id===b.dataset.id);try{if(b.dataset.action==='close'){issued=null;byId('dialog').close()}else if(b.dataset.action==='copy'&&issued){await navigator.clipboard.writeText(`IC Study\n${location.origin}\nTên đăng nhập: ${issued.username}\nMật khẩu: ${issued.password}`);b.textContent='Đã sao chép ✓'}else if(b.dataset.action==='toggle'&&u){await request('/api/admin/users/'+u.id,'PATCH',{disabled:!u.disabled});await load()}else if(b.dataset.action==='reset'&&u){showDialog(`<h2>Đặt lại mật khẩu?</h2><p class="muted">${escapeHtml(u.name)} sẽ được cấp mật khẩu ngẫu nhiên mới và đăng xuất khỏi các thiết bị đang dùng.</p><button class="primary" data-action="confirm-reset" data-id="${u.id}">Cấp mật khẩu mới</button>`)}else if(b.dataset.action==='confirm-reset'&&u){credentials(await request('/api/admin/users/'+u.id+'/reset-password','POST',{}))}else if(b.dataset.action==='detail'&&u){showDialog(`<h2>${escapeHtml(u.name)}</h2><p class="muted">Đồng bộ gần nhất: ${u.updatedAt?new Date(u.updatedAt).toLocaleString('vi-VN'):'Chưa có bài làm'}<br>Đăng nhập gần nhất: ${u.lastLogin?new Date(u.lastLogin).toLocaleString('vi-VN'):'Chưa đăng nhập'}</p><div class="course-bars">${Object.entries(u.progress.subjects).map(([code,s])=>`<label>${code}<small>${s.done}/${s.total} · ${s.right} đúng</small><div class="bar"><i style="width:${s.done/s.total*100}%"></i></div></label>`).join('')}</div><h3 style="font-size:15px;margin-top:25px">Các phiên gần đây</h3><ul class="muted">${u.progress.sessions.map(s=>`<li>${({practice:'Luyện tập',exam:'Thi thử',flash:'Thẻ ghi nhớ',mistakes:'Luyện câu sai'})[s.mode]||'Phiên học'} · ${s.answered}/${s.total} câu · ${s.updated?new Date(s.updated).toLocaleString('vi-VN'):''}</li>`).join('')||'<li>Chưa có phiên đã đồng bộ.</li>'}</ul>`)}}catch(e){byId('error').textContent=e.message}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="delete-user"]');if(!b)return;const u=icUsers.find(u=>u.id===b.dataset.id);if(!u)return;showDialog(`<h2>Xóa tài khoản học viên?</h2><p class="muted"><strong>${escapeHtml(u.name)}</strong> · ${escapeHtml(u.username)}</p><p class="delete-warning">Thao tác này xóa tài khoản, tiến độ và các phiên học đã đồng bộ của học viên, đồng thời đăng xuất khỏi mọi thiết bị. Không thể khôi phục sau khi xóa.</p><form id="delete-user-form" data-id="${u.id}"><label>Nhập tên đăng nhập để xác nhận: <strong>${escapeHtml(u.username)}</strong><input id="delete-username" name="username" autocomplete="off" autocapitalize="none" spellcheck="false" required></label><p class="error" id="delete-error" role="alert"></p><button class="danger" id="delete-confirm" disabled>Xóa vĩnh viễn tài khoản</button></form>`)});
document.addEventListener('input',e=>{if(e.target.id!=='delete-username')return;const u=icUsers.find(u=>u.id===byId('delete-user-form')?.dataset.id);byId('delete-confirm').disabled=!u||e.target.value!==u.username});
document.addEventListener('submit',async e=>{if(e.target.id!=='delete-user-form')return;e.preventDefault();const u=icUsers.find(u=>u.id===e.target.dataset.id),button=byId('delete-confirm');if(!u||e.target.elements.username.value!==u.username)return;button.disabled=true;button.textContent='Đang xóa…';try{await request('/api/admin/users/'+u.id,'DELETE',{username:u.username});byId('dialog').close();await load()}catch(e){byId('delete-error').textContent=e.message;button.disabled=false;button.textContent='Xóa vĩnh viễn tài khoản'}});
load();setInterval(()=>{if(!byId('dialog').open)load()},15000);
